import React from "react";
import {
  FaCode,
  FaAward,
  FaBriefcase,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain,
  FaChartLine
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      {/* BACKGROUND EFFECTS */}
      <div className="bg-glow"></div>

      {/* HEADER */}
      <div className="header">
        <h1>Skills & Expertise</h1>
        <p>My technical abilities, learning journey, and real-world experience in development and data analytics.</p>
      </div>

      {/* TOP GRID */}
      <div className="grid">

        {/* TECHNICAL SKILLS */}
        <div className="card">
          <h2><FaCode /> Technical Skills</h2>
          <div className="tags">
            <span>Java</span>
            <span>React.js</span>
            <span>Spring Boot</span>
            <span>MySQL</span>
            <span>HTML & CSS</span>
          </div>
        </div>

        {/* CERTIFICATIONS */}
        <div className="card">
          <h2><FaAward /> Certifications</h2>
          <div className="tags">
            <span>Java Programming</span>
            <span>Data Science (NPTEL)</span>
            <span>SQL</span>
            <span>Python</span>
          </div>
        </div>

      </div>

      {/* INTERNSHIPS */}
      <div className="section-title">
        <h2>Internship Experience</h2>
      </div>

      <div className="intern-grid">

        {/* FULL STACK INTERNSHIP */}
        <div className="card wide">
          <div className="badge">01</div>
          <h2><FaBriefcase /> Full Stack Java Internship</h2>
          <span className="company">Retech Solutions</span>

          <p>
            Gained hands-on experience in Full Stack Java development,
            including frontend design, backend development using Spring Boot,
            and database integration. Built a Student Portal Management System
            with authentication and structured data handling.
          </p>
        </div>

        {/* DATA ANALYTICS INTERNSHIP */}
        <div className="card wide">
          <div className="badge">02</div>
          <h2><FaChartLine /> Data Analytics Internship</h2>
          <span className="company">Power BI Training Program</span>

          <p>
            Successfully completed internship in Data Analytics with hands-on
            experience in Power BI. Built interactive dashboards, performed data cleaning,
            visualization, and transformed raw datasets into meaningful insights for decision-making.
            Strengthened analytical thinking and reporting skills through real-world projects.
          </p>
        </div>

      </div>

      {/* SOFT SKILLS */}
      <div className="card soft">
        <h2><FaUsers /> Soft Skills</h2>

        <div className="tags">
          <span><FaUsers /> Teamwork</span>
          <span><FaComments /> Communication</span>
          <span><FaLightbulb /> Problem Solving</span>
          <span><FaCogs /> Adaptability</span>
          <span><FaBrain /> Creativity</span>
          <span><FaUsersCog /> Leadership</span>
          <span><FaClock /> Time Management</span>
        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .skills-page {
          min-height: 100vh;
          padding: 40px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          position: relative;
          overflow: hidden;
        }

        /* GLOW BACKGROUND */
        .bg-glow {
          position: absolute;
          width: 600px;
          height: 600px;
          background: radial-gradient(circle, rgba(56,189,248,0.15), transparent 60%);
          top: -200px;
          left: -200px;
          filter: blur(60px);
          animation: move 10s infinite alternate;
        }

        @keyframes move {
          0% { transform: translate(0,0); }
          100% { transform: translate(100px,80px); }
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 40px;
        }

        .header h1 {
          font-size: 42px;
          color: #38BDF8;
        }

        .header p {
          color: #94a3b8;
          margin-top: 10px;
        }

        /* GRID */
        .grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 25px;
          margin-bottom: 40px;
        }

        .intern-grid {
          display: grid;
          grid-template-columns: 1fr;
          gap: 20px;
          margin-bottom: 40px;
        }

        /* CARD */
        .card {
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          padding: 20px;
          border-radius: 16px;
          transition: 0.3s;
          position: relative;
          backdrop-filter: blur(8px);
        }

        .card:hover {
          transform: translateY(-6px);
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
          border-color: #38BDF8;
        }

        /* WIDE CARD */
        .wide {
          padding: 25px;
        }

        /* BADGE */
        .badge {
          position: absolute;
          top: 12px;
          right: 12px;
          width: 28px;
          height: 28px;
          border-radius: 8px;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 12px;
          background: linear-gradient(135deg, #38BDF8, #60a5fa);
          color: #0b1220;
          font-weight: 600;
        }

        /* TITLES */
        h2 {
          display: flex;
          align-items: center;
          gap: 10px;
          color: #38BDF8;
          margin-bottom: 10px;
        }

        /* COMPANY */
        .company {
          display: inline-block;
          margin-bottom: 10px;
          padding: 4px 10px;
          border-radius: 12px;
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
          font-size: 12px;
        }

        /* TAGS */
        .tags {
          display: flex;
          flex-wrap: wrap;
          gap: 10px;
        }

        .tags span {
          padding: 6px 12px;
          border-radius: 20px;
          background: rgba(56,189,248,0.1);
          border: 1px solid rgba(56,189,248,0.3);
          font-size: 13px;
          color: #cbd5e1;
        }

        /* SOFT SKILLS */
        .soft {
          margin-top: 10px;
        }

        @media (max-width: 900px) {
          .grid {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Skills;
